#!/usr/bin/env bash
set -euo pipefail

# Build/verification imports must not write generated bytecode into source.
export PYTHONDONTWRITEBYTECODE=1
export GOENV=off
export GOFLAGS=

build_dir=$(cd "$(dirname "$0")" && pwd)
root=$(cd "$build_dir/../.." && pwd)
build_root=${REPLICARO_TARGET_OUT:?target-contained output root is required}
target=${1:?linux_amd64 or linux_arm64}
case "$target" in
  linux_amd64) deb_arch=amd64; rpm_arch=x86_64; appimage_arch=x86_64; host_arch=x86_64 ;;
  linux_arm64) deb_arch=arm64; rpm_arch=aarch64; appimage_arch=aarch64; host_arch=aarch64 ;;
  *) echo "target must be linux_amd64 or linux_arm64" >&2; exit 2 ;;
esac
if [[ "$(uname -m)" != "$host_arch" ]]; then
  echo "$target packages must be produced on a native $host_arch builder" >&2
  exit 2
fi
for tool in dpkg-deb rpm rpmbuild tar sha256sum curl file appstreamcli; do
  command -v "$tool" >/dev/null || { echo "$tool is required to build Linux packages" >&2; exit 2; }
done
(cd "$root/backend" && go run -mod=readonly ./tools/targetverify --target "$target")
[[ "${REPLICARO_SIGNED_BUILD:-0}" == 0 ]] || { echo "This public packager only creates unsigned outputs." >&2; exit 2; }

version=$(node -p 'require(process.argv[1]).version' "$root/frontend/package.json")
deb_output="$build_root/replicaro-$version-$target.deb"
rpm_output="$build_root/replicaro-$version-$target.rpm"
appimage_output="$build_root/Replicaro-$version-$target.AppImage"
for output in "$deb_output" "$rpm_output" "$appimage_output"; do
  [[ ! -e "$output" && ! -L "$output" ]] || { echo "refusing to replace Linux distribution output: $output" >&2; exit 2; }
done
bundle="$build_root/replicaro-$target-bundle"
binary="$build_root/replicaro-$target"
[[ -x "$binary" && -f "$bundle/LICENSES.txt" && -f "$build_root/provenance/manifest.json" ]] || { echo "build-linux.sh must create the target bundle first" >&2; exit 2; }
grep -Fq '"frontend":"embedded"' "$build_root/provenance/manifest.json" || { echo "target bundle does not declare its embedded frontend" >&2; exit 2; }
source_date_epoch=${SOURCE_DATE_EPOCH:?canonical build epoch is required}
work=$(mktemp -d "${TMPDIR:-/tmp}/replicaro-linux-packaging-$target.XXXXXX")
cleanup() { [[ ! -d "$work" ]] || find "$work" -depth -delete; }
trap cleanup EXIT
build_timestamp=${REPLICARO_BUILD_TIMESTAMP:?canonical build timestamp is required}
validated_source_date_epoch=$(cd "$build_dir" && go run ./cmd/contract timestamp --value "$build_timestamp")
[[ "$validated_source_date_epoch" == "$source_date_epoch" ]] || { echo "build timestamp and canonical build epoch differ" >&2; exit 2; }
appstream_release_date=${build_timestamp%%T*}

write_desktop() {
  local output=$1 executable=$2
  sed "s|@REPLICARO_EXECUTABLE@|$executable|g" "$bundle/share/applications/replicaro.desktop" > "$output"
}

write_service() {
  local output=$1 executable=$2
  sed "s|@REPLICARO_EXECUTABLE@|$executable|g" "$bundle/share/systemd/user/replicaro.service" > "$output"
}

write_metainfo() {
  local output=$1
  cat > "$output" <<METAINFO
<?xml version="1.0" encoding="UTF-8"?>
<component type="desktop-application">
  <id>io.replicaro.desktop</id>
  <name>Replicaro</name>
  <developer_name>Replicaro.com</developer_name>
  <summary>Local backup companion</summary>
  <metadata_license>CC0-1.0</metadata_license>
  <project_license>Apache-2.0</project_license>
  <description><p>Replicaro manages local and cloud backup repositories through a local web interface.</p></description>
  <url type="homepage">https://replicaro.com</url>
  <launchable type="desktop-id">replicaro.desktop</launchable>
  <releases><release version="$version" date="$appstream_release_date"/></releases>
</component>
METAINFO
}

populate_system_root() {
  local destination=$1
  mkdir -p "$destination/opt/replicaro" "$destination/usr/bin" \
    "$destination/usr/share/applications" "$destination/usr/share/icons/hicolor/256x256/apps" \
    "$destination/usr/share/metainfo" "$destination/usr/lib/systemd/user" \
    "$destination/usr/share/doc/replicaro"
  install -m 755 "$binary" "$destination/opt/replicaro/replicaro"
  install -m 644 "$bundle/LICENSES.txt" "$destination/usr/share/doc/replicaro/LICENSES.txt"
  install -m 644 "$bundle/share/icons/hicolor/256x256/apps/replicaro.png" "$destination/usr/share/icons/hicolor/256x256/apps/replicaro.png"
  write_desktop "$destination/usr/share/applications/replicaro.desktop" /opt/replicaro/replicaro
  write_service "$destination/usr/lib/systemd/user/replicaro.service" /opt/replicaro/replicaro
  write_metainfo "$destination/usr/share/metainfo/io.replicaro.desktop.metainfo.xml"
  chmod 644 "$destination/usr/share/applications/replicaro.desktop" "$destination/usr/lib/systemd/user/replicaro.service" "$destination/usr/share/metainfo/io.replicaro.desktop.metainfo.xml"
  ln -s ../../opt/replicaro/replicaro "$destination/usr/bin/replicaro"
}

deb_root="$work/deb"
populate_system_root "$deb_root"
mkdir -p "$deb_root/DEBIAN"
installed_size=$(du -sk "$deb_root" | awk '{print $1}')
cat > "$deb_root/DEBIAN/control" <<CONTROL
Package: replicaro
Version: $version
Section: utils
Priority: optional
Architecture: $deb_arch
Maintainer: Replicaro.com <backup@replicaro.com>
Homepage: https://replicaro.com
Depends: openssh-client
Installed-Size: $installed_size
Description: Local backup companion
 Replicaro manages local and cloud backup repositories through a local web interface.
CONTROL
chmod 755 "$deb_root/DEBIAN"; chmod 644 "$deb_root/DEBIAN/control"
find "$deb_root" -exec touch -h -d "@$source_date_epoch" {} +
deb_temporary="$work/$(basename "$deb_output")"
SOURCE_DATE_EPOCH=$source_date_epoch dpkg-deb --root-owner-group -Zxz -z6 --build "$deb_root" "$deb_temporary" >/dev/null
mv "$deb_temporary" "$deb_output"

rpm_payload="$work/rpm-payload"
populate_system_root "$rpm_payload"
rpm_top="$work/rpmbuild"
mkdir -p "$rpm_top/BUILD" "$rpm_top/BUILDROOT" "$rpm_top/RPMS" "$rpm_top/SOURCES" "$rpm_top/SPECS" "$rpm_top/SRPMS" "$rpm_top/rpmdb"
rpm --dbpath "$rpm_top/rpmdb" --initdb
tar --sort=name --mtime="@$source_date_epoch" --owner=0 --group=0 --numeric-owner -C "$rpm_payload" -czf "$rpm_top/SOURCES/payload.tar.gz" .
cat > "$rpm_top/SPECS/replicaro.spec" <<SPEC
Name: replicaro
Version: $version
Release: 1
Summary: Local backup companion
License: Apache-2.0
Vendor: Replicaro.com
URL: https://replicaro.com
BuildArch: $rpm_arch
AutoReqProv: no
Requires: openssh-clients
Source0: payload.tar.gz

%description
Replicaro manages local and cloud backup repositories through a local web interface.

%prep
%build
%install
mkdir -p "%{buildroot}"
tar -xzf "%{SOURCE0}" -C "%{buildroot}"

%files
/opt/replicaro
/usr/bin/replicaro
/usr/lib/systemd/user/replicaro.service
/usr/share/applications/replicaro.desktop
/usr/share/icons/hicolor/256x256/apps/replicaro.png
/usr/share/metainfo/io.replicaro.desktop.metainfo.xml
/usr/share/doc/replicaro

%changelog
* Wed Jul 22 2026 Replicaro.com - $version-1
- Native $target package
SPEC
SOURCE_DATE_EPOCH=$source_date_epoch rpmbuild -bb --define "_topdir $rpm_top" --define "_dbpath $rpm_top/rpmdb" \
  --define "_buildhost replicaro-build" --define "use_source_date_epoch_as_buildtime 1" \
  --define "clamp_mtime_to_source_date_epoch 1" --define "_build_id_links none" \
  --define "__os_install_post %{nil}" "$rpm_top/SPECS/replicaro.spec" >/dev/null
rpm_built=$(find "$rpm_top/RPMS" -type f -name '*.rpm' -print -quit)
[[ -n "$rpm_built" ]] || { echo "rpmbuild did not produce an RPM" >&2; exit 1; }
mv "$rpm_built" "$rpm_output"

appdir="$work/Replicaro.AppDir"
mkdir -p "$appdir/usr/bin" \
  "$appdir/usr/share/replicaro" \
  "$appdir/usr/share/applications" "$appdir/usr/share/icons/hicolor/256x256/apps" "$appdir/usr/share/metainfo"
install -m 755 "$binary" "$appdir/usr/bin/replicaro"
install -m 644 "$bundle/LICENSES.txt" "$appdir/usr/share/replicaro/LICENSES.txt"
install -m 644 "$bundle/share/icons/hicolor/256x256/apps/replicaro.png" "$appdir/usr/share/icons/hicolor/256x256/apps/replicaro.png"
write_metainfo "$appdir/usr/share/metainfo/io.replicaro.desktop.metainfo.xml"
cat > "$appdir/AppRun" <<'APPRUN'
#!/bin/sh
set -eu
appdir=${APPDIR:-$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)}
export REPLICARO_APPIMAGE_ICON_THEME_PATH="$appdir/usr/share/icons/hicolor/256x256/apps"
exec "$appdir/usr/bin/replicaro" "$@"
APPRUN
chmod 755 "$appdir/AppRun"
cat > "$appdir/replicaro.desktop" <<DESKTOP
[Desktop Entry]
Type=Application
Name=Replicaro
Exec=replicaro
Terminal=false
Categories=Utility;Archiving;
Icon=replicaro
X-AppImage-Version=$version
DESKTOP
cp "$appdir/replicaro.desktop" "$appdir/usr/share/applications/replicaro.desktop"
cp "$appdir/usr/share/icons/hicolor/256x256/apps/replicaro.png" "$appdir/replicaro.png"
ln -s replicaro.png "$appdir/.DirIcon"
appstreamcli validate-tree --no-net "$appdir"
find "$appdir" -exec touch -h -d "@$source_date_epoch" {} +
appimagetool=$(REPLICARO_TARGET_OUT="$build_root" bash "$build_dir/acquire-appimagetool.sh" "$target")
appimage_runtime=$(REPLICARO_TARGET_OUT="$build_root" bash "$build_dir/acquire-appimage-runtime.sh" "$target")
appimage_temporary="$work/$(basename "$appimage_output")"
appimage_arguments=(--no-appstream --runtime-file "$appimage_runtime")
ARCH=$appimage_arch VERSION=$version SOURCE_DATE_EPOCH=$source_date_epoch APPIMAGE_EXTRACT_AND_RUN=1 \
  "$appimagetool" "${appimage_arguments[@]}" "$appdir" "$appimage_temporary" >/dev/null
chmod 755 "$appimage_temporary"
mv "$appimage_temporary" "$appimage_output"

tarball="$build_root/replicaro-$version-$target.tar.gz"
[[ -f "$tarball" ]] || { echo "portable tarball is missing" >&2; exit 2; }
printf 'Linux distributions created for %s: DEB, RPM, AppImage, tarball\n' "$target"
